  "protocol-schema": "2.1.0",
  "metadata": {
    "protocol-name": "Sample Pipetting Protocol",
    "author": "Opentrons Team",
    "description": "A basic protocol for aspirating and dispensing liquid using a pipette.",
    "created": 1620000000,
    "last-modified": 1620000000,
    "category": "Basic Pipetting",
    "subcategory": "Sample Transfer",
    "tags": ["pipette", "aspirate", "dispense"]
  },
  "default-values": {
    "aspirate-flow-rate": {
      "p10_single": 1.0,
      "p10_multi": 1.0,
      "p50_single": 1.0,
      "p50_multi": 1.0,
      "p300_single": 1.0,
      "p300_multi": 1.0,
      "p1000_single": 1.0,
      "p1000_multi": 1.0
    },
    "dispense-flow-rate": {
      "p10_single": 1.0,
      "p10_multi": 1.0,
      "p50_single": 1.0,
      "p50_multi": 1.0,
      "p300_single": 1.0,
      "p300_multi": 1.0,
      "p1000_single": 1.0,
      "p1000_multi": 1.0
    },
    "aspirate-mm-from-bottom": 2.0,
    "dispense-mm-from-bottom": 2.0,
    "touch-tip-mm-from-top": 1.0
  },
  "designer-application": {
    "application-name": "opentrons/protocol-designer",
    "application-version": "2.1.0",
    "data": {}
  },
  "robot": {
    "model": "OT-2 Standard"
  },
  "pipettes": {
    "pipette1": {
      "mount": "left",
      "name": "p300_single",
      "model": "p300_single_v1.3"
    }
  },
  "labware": {
    "labware1": {
      "slot": "1",
      "model": "96-flat",
      "display-name": "Source Plate"
    },
    "labware2": {
      "slot": "2",
      "model": "96-flat",
      "display-name": "Destination Plate"
    }
  },
  "procedure": [
    {
      "annotation": {
        "name": "Aspirate from source plate",
        "description": "Aspirate 50 µL from source plate."
      },
      "subprocedure": [
        {
          "command": "aspirate",
          "params": {
            "pipette": "pipette1",
            "labware": "labware1",
            "well": "A1",
            "volume": 50,
            "flow-rate": 1.0,
            "offsetFromBottomMm": 2.0
          }
        }
      ]
    },
    {
      "annotation": {
        "name": "Dispense to destination plate",
        "description": "Dispense 50 µL to destination plate."
      },
      "subprocedure": [
        {
          "command": "dispense",
          "params": {
            "pipette": "pipette1",
            "labware": "labware2",
            "well": "A1",
            "volume": 50,
            "flow-rate": 1.0,
            "offsetFromBottomMm": 2.0
          }
        }
      ]
    }
  ]
}

