{
  "name": "apex-api",
  "description": "Public API for Apex services",
  "type": "server",
  "profile": "apex-prod",
  "regions": ["us-west-2", "eu-west-1"],
  "lambda": {
    "accelerate": true,
    "warm": true,
    "warm_rate": "5m",
    "warm_count": 10,
    "memory": 1024
  },
  "stages": {
    "production": {
      "domain": "api.apex.sh"
    },
    "staging": {
      "domain": "api-staging.apex.sh"
    },
    "development": {
      "domain": "api-dev.apex.sh"
    }
  },
  "hooks": {
    "build": "npm install && npm run build",
    "clean": "rm -rf dist/*",
    "prebuild": "npm run lint",
    "postbuild": "npm run test",
    "predeploy": "echo 'Predeploying...'",
    "postdeploy": "echo 'Postdeploying...'"
  },
  "static": {
    "dir": "./dist",
    "prefix": "/static/"
  },
  "proxy": {
    "command": "node server.js",
    "timeout": 30,
    "listen_timeout": 30,
    "shutdown_timeout": 30,
    "backoff": {
      "min": 500,
      "max": 1500,
      "factor": 1.5,
      "attempts": 5,
      "jitter": true
    }
  },
  "error_pages": {
    "disable": false,
    "dir": "./error-pages",
    "variables": {
      "support_email": "support@apex.sh",
      "color": "#228ae6"
    }
  },
  "cors": {
    "enable": true,
    "allowed_origins": ["https://*.apex.sh", "https://apex.sh"],
    "allowed_methods": ["GET", "POST", "PUT", "DELETE", "HEAD"],
    "allowed_headers": ["Content-Type", "Authorization"],
    "exposed_headers": ["Content-Type", "Authorization"],
    "max_age": 60,
    "allowed_credentials": true
  },
  "actions": [
    {
      "name": "email.backend",
      "type": "email",
      "emails": ["backend@apex.sh"]
    },
    {
      "name": "sms.backend",
      "type": "sms",
      "numbers": ["+12508004123"]
    }
  ],
  "alerts": [
    {
      "metric": "http.latency",
      "statistic": "avg",
      "threshold": 500,
      "action": "email.backend",
      "period": "1m",
      "evaluation_periods": 2,
      "operator": ">",
      "namespace": "AWS/ApiGateway",
      "description": "High latency detected",
      "disable": false
    },
    {
      "metric": "http.5xx",
      "statistic": "count",
      "threshold": 10,
      "action": "sms.backend",
      "period": "5m",
      "evaluation_periods": 1,
      "operator": ">",
      "namespace": "AWS/ApiGateway",
      "description": "High error rate detected",
      "disable": false
    }
  ]
}

